function saveConfig(force)
	if _cfgLoading and not force then return end
	if not writefile then return end
	local ok,json=pcall(function() return HS:JSONEncode(buildConfigTable()) end)
	if not ok or not json then return end
	if json==_lastCfgJson and not force then return end
	-- kalau gagal nulis, _lastCfgJson tidak diubah sehingga autosave coba lagi
	if pcall(writefile,CONFIG_MAIN_FILE,json) then _lastCfgJson=json end
end

-- ---------- Config profile (SAVE / LOAD / DELETE by name) ----------
function cfgSanitizeName(name)
	name=tostring(name or "")
	name=name:gsub("^%s+",""):gsub("%s+$","")
	name=name:gsub("[^%w_%-%s]","_")
	name=name:gsub("%s+","_")
	return name:sub(1,32)
end
function cfgEnsureDir()
	if not makefolder then return end
	pcall(function() if not (isfolder and isfolder(CONFIG_DIR)) then makefolder(CONFIG_DIR) end end)
	pcall(function() if not (isfolder and isfolder(CONFIG_PROFILE_DIR)) then makefolder(CONFIG_PROFILE_DIR) end end)
end
function cfgProfilePath(name) return CONFIG_PROFILE_DIR.."/"..name..".json" end
function listConfigProfiles()
	local out={}
	if not listfiles then return out end
	cfgEnsureDir()
	local ok,files=pcall(listfiles,CONFIG_PROFILE_DIR)
	if not ok or type(files)~="table" then return out end
	for _,f in ipairs(files) do
		local n=tostring(f):match("([^/\\]+)%.json$")
		if n then out[#out+1]=n end
	end
	table.sort(out,function(x,y) return x:lower()<y:lower() end)
	return out
end
function saveConfigProfile(name)
	name=cfgSanitizeName(name)
	if name=="" then return false,"Isi nama config dulu" end
	if not writefile then return false,"Executor tidak support writefile" end
	cfgEnsureDir()
	local ok,json=pcall(function() return HS:JSONEncode(buildConfigTable()) end)
	if not ok or not json then return false,"Gagal encode config" end
	if not pcall(writefile,cfgProfilePath(name),json) then return false,"Gagal nulis file" end
	saveConfig()
	return true,"Tersimpan: "..name
end
function loadConfigProfile(name)
	name=cfgSanitizeName(name)
	if name=="" then return false,"Isi nama config dulu" end
	if not (readfile and isfile) then return false,"Executor tidak support readfile" end
	local path=cfgProfilePath(name)
	if not isfile(path) then return false,"Config '"..name.."' tidak ada" end
	local ok,cfg=pcall(function() return HS:JSONDecode(readfile(path)) end)
	if not ok or type(cfg)~="table" then return false,"File config rusak" end
	if not applyConfigRuntime then return false,"Belum siap, coba lagi" end
	applyConfigRuntime(cfg)
	return true,"Loaded: "..name
end
function deleteConfigProfile(name)
	name=cfgSanitizeName(name)
	if name=="" then return false,"Isi nama config dulu" end
	if not (delfile and isfile) then return false,"Executor tidak support delfile" end
	local path=cfgProfilePath(name)
	if not isfile(path) then return false,"Config '"..name.."' tidak ada" end
	if not pcall(delfile,path) then return false,"Gagal hapus file" end
	return true,"Dihapus: "..name
end
