					if not (writefile and getcustomasset and isfile and game.HttpGet) then return end
					local fileName = "intro_music_" .. tostring(INTRO_MUSIC_INDEX) .. ".mp3"
					if not isfile(fileName) then
						local okDl, data = pcall(function() return game:HttpGet(AUDIO_URLS[INTRO_MUSIC_INDEX]) end)
						if not okDl or not data then return end
						writefile(fileName, data)
					end
					local okAsset, assetId = pcall(getcustomasset, fileName)
					if not okAsset or not assetId or closed or not screen or not screen.Parent then return end
					local snd = Instance.new("Sound")
					snd.Name = "IntroMusic"
					snd.SoundId = assetId
					snd.Volume = 1
					snd.Looped = true
					snd.Parent = screen
					introSound = snd
					snd:Play()
				end)
			end)

			local group = make("CanvasGroup", screen, {Name = "ZurichIntro", Size = UDim2.fromScale(1, 1),
				BackgroundTransparency = 1, Active = true, ZIndex = 1})

			local bg = make("Frame", group, {Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.fromRGB(4, 4, 12),
				BackgroundTransparency = 1, ZIndex = 1})
			local vignette = make("Frame", group, {Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
				BackgroundTransparency = 1, ZIndex = 2})
			make("UIGradient", vignette, {Color = ColorSequence.new(Color3.new(0, 0, 0)),
				Transparency = NumberSequence.new({
					NumberSequenceKeypoint.new(0, 0.3),
					NumberSequenceKeypoint.new(0.5, 0.85),
					NumberSequenceKeypoint.new(1, 0.3),
				}), Rotation = 90})

			local function newImage(assetId, zIndex, colorTint, transparency)
				return make("ImageLabel", group, {BackgroundTransparency = 1, Image = assetId,
					ScaleType = Enum.ScaleType.Fit, ZIndex = zIndex,
					ImageColor3 = colorTint or Color3.new(1, 1, 1), ImageTransparency = transparency or 1})
			end

			local function newLogoText(zIndex, color)
				return make("TextLabel", group, {AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1,
					Text = INTRO_TEXT, TextScaled = true, Font = Enum.Font.GothamBlack, TextColor3 = color,
					TextTransparency = 1, TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 1,
					ZIndex = zIndex, Size = UDim2.new(0.5, 0, 0.35, 0), Position = UDim2.new(0.5, 0, 0.42, 0)})
			end

			local function spawnTrailGhost(refImg, zIndex)
				local ghost = newImage(KATANA_ID, zIndex, INTRO_COLOR, 0.55)
				ghost.AnchorPoint = refImg.AnchorPoint
				ghost.Position = refImg.Position
				ghost.Size = refImg.Size
				ghost.Rotation = refImg.Rotation
				task.spawn(function()
					for i = 1, 20 do
						if not ghost.Parent then return end
						ghost.ImageTransparency = 0.55 + (i / 20) * 0.45
						task.wait(1 / 60)
					end
					ghost:Destroy()
				end)
			end

			local function easeOutCubic(t) return 1 - (1 - t) ^ 3 end
			local function easeOutBack(t)
				local c1 = 1.70158
				local c3 = c1 + 1
				return 1 + c3 * (t - 1) ^ 3 + c1 * (t - 1) ^ 2
			end

			local katanaL = newImage(KATANA_ID, 10, INTRO_COLOR)
			katanaL.Position = UDim2.new(-0.35, 0, 0.8, 0)
			katanaL.Rotation = -60
			katanaL.Size = UDim2.new(0.22, 0, 0.34, 0)
			katanaL.ImageTransparency = 0

			local katanaR = newImage(KATANA_ID, 10, INTRO_COLOR)
			katanaR.Position = UDim2.new(1.35, 0, 0.8, 0)
			katanaR.Rotation = 60
			katanaR.Size = UDim2.new(0.22, 0, 0.34, 0)
			katanaR.ImageTransparency = 0

			local logo = newLogoText(20, Color3.new(1, 1, 1))
			local logoGlow = newLogoText(19, Color3.fromRGB(0, 150, 255))
			local function setLogoAlpha(t)
				logo.TextTransparency = 1 - t
				logo.TextStrokeTransparency = 1 - t * 0.6
			end

			-- tombol skip intro
			local skipButton = round(make("TextButton", screen, {Name = "Skip", Size = UDim2.fromOffset(128, 38),
				Position = UDim2.new(1, -20, 0, 16), AnchorPoint = Vector2.new(1, 0),
				BackgroundColor3 = Color3.new(1, 1, 1), Text = "SKIP INTRO  »", TextColor3 = Color3.new(0, 0, 0),
				Font = Enum.Font.GothamBlack, TextSize = 13, AutoButtonColor = false, ZIndex = 10}), 10)
			connect(skipButton.MouseEnter, function() skipButton.BackgroundColor3 = Color3.fromRGB(200, 200, 200) end)
			connect(skipButton.MouseLeave, function() skipButton.BackgroundColor3 = Color3.new(1, 1, 1) end)

			local function playSequence()
				for i = 1, 36 do
					if not alive() then return end
					bg.BackgroundTransparency = 1 - (i / 36) * 0.65
					vignette.BackgroundTransparency = 1 - (i / 36) * 0.5
					task.wait(1 / 60)
				end
				task.wait(0.15)

				local lStart, lMid = katanaL.Position, UDim2.new(0.62, 0, 0.05, 0)
				local rStart, rMid = katanaR.Position, UDim2.new(0.05, 0, 0.05, 0)
				for i = 1, 36 do
					if not alive() then return end
					local ease = easeOutCubic(i / 36)
					katanaL.Position = lStart:Lerp(lMid, ease)
					katanaL.Rotation = -60 + (ease * 15)
					katanaR.Position = rStart:Lerp(rMid, ease)
					katanaR.Rotation = 60 - (ease * 15)
					if i % 3 == 0 then
						spawnTrailGhost(katanaL, 8)
						spawnTrailGhost(katanaR, 8)
					end
					task.wait(1 / 60)
				end
				task.wait(0.1)

				local lFinalPos = UDim2.new(0.16, 0, 0.55, 0)
				local lFinalSize = UDim2.new(0.24, 0, 0.38, 0)
				local rFinalPos = UDim2.new(0.84, 0, 0.55, 0)
				local rFinalSize = UDim2.new(0.24, 0, 0.38, 0)
				katanaL.AnchorPoint = Vector2.new(0, 0.5)
				katanaR.AnchorPoint = Vector2.new(1, 0.5)
				local lSettleStart, lSettleRot = katanaL.Position, katanaL.Rotation
				local rSettleStart, rSettleRot = katanaR.Position, katanaR.Rotation
				for i = 1, 33 do
					if not alive() then return end
					local t = i / 33
					local clampedEase = math.min(easeOutBack(t), 1.15)
					katanaL.Position = lSettleStart:Lerp(lFinalPos, clampedEase)
					katanaL.Rotation = lSettleRot + (clampedEase * (-15 - lSettleRot))
					katanaL.Size = katanaL.Size:Lerp(lFinalSize, t)
					katanaR.Position = rSettleStart:Lerp(rFinalPos, clampedEase)
					katanaR.Rotation = rSettleRot + (clampedEase * (15 - rSettleRot))
					katanaR.Size = katanaR.Size:Lerp(rFinalSize, t)
					task.wait(1 / 60)
				end
				katanaL.Position, katanaL.Rotation, katanaL.Size = lFinalPos, -15, lFinalSize
				katanaR.Position, katanaR.Rotation, katanaR.Size = rFinalPos, 15, rFinalSize

				local floatStart = tick()
				local floating = true
				task.spawn(function()
					while floating and alive() do
						local t = tick() - floatStart
						katanaL.Rotation = -15 + math.sin(t * 1.2) * 25
						katanaR.Rotation = 15 + math.sin(t * 1.2 + math.pi) * 25
						local offsetX = math.sin(t * 0.9) * 0.025
						local offsetY = math.sin(t * 1.7) * 0.018
						katanaL.Position = UDim2.new(lFinalPos.X.Scale + offsetX, 0, lFinalPos.Y.Scale + offsetY, 0)
						katanaR.Position = UDim2.new(rFinalPos.X.Scale - offsetX, 0, rFinalPos.Y.Scale + offsetY, 0)
						task.wait(1 / 60)
					end
				end)
				task.wait(0.5)

				local logoStartSize, logoEndSize = UDim2.new(0.35, 0, 0.24, 0), UDim2.new(0.5, 0, 0.35, 0)
				local glowStartSize, glowEndSize = UDim2.new(0.42, 0, 0.28, 0), UDim2.new(0.58, 0, 0.4, 0)
				for i = 1, 42 do
					if not alive() then floating = false; return end
					local t = i / 42
					local ease = math.min(easeOutBack(t), 1)
					setLogoAlpha(t)
					logo.Size = logoStartSize:Lerp(logoEndSize, ease)
					logoGlow.TextTransparency = 1 - (t * 0.5)
					logoGlow.Size = glowStartSize:Lerp(glowEndSize, ease)
					task.wait(1 / 60)
				end
				task.spawn(function()
					for i = 1, 90 do
						if not alive() then return end
						logoGlow.TextTransparency = 0.5 + math.sin(i / 12) * 0.15
						task.wait(1 / 60)
					end
				end)
				task.wait(1.9)

				floating = false
				for i = 1, 60 do
					if not alive() then return end
					local t = i / 60
					bg.BackgroundTransparency = 0.35 + t * 0.65
					vignette.BackgroundTransparency = 0.5 + t * 0.5
					katanaL.ImageTransparency = t
					katanaR.ImageTransparency = t
					logo.TextTransparency = t
					logo.TextStrokeTransparency = 0.4 + t * 0.6
					logoGlow.TextTransparency = 0.5 + t * 0.5
					task.wait(1 / 60)
				end
			end

			local function runSequence()
				local okSeq, errSeq = pcall(playSequence)
				if not okSeq then warn("[NANZ HUB V2] Intro: " .. tostring(errSeq)) end
				exit()
			end

			connect(skipButton.Activated, exit)
			connect(UIS.InputBegan, function(input, gpe)
				if not gpe and input.KeyCode == Enum.KeyCode.Escape then exit() end
			end)
			started = tick()
			local function render()
				if closed then return end
				if tick() - started >= duration then exit() end
				if leaving then
					skipButton.Visible = false
					local a = math.clamp((tick() - leaving) / exitFadeDuration, 0, 1)
					group.GroupTransparency = a
					if a >= 1 then closed = true end
				end
			end
			connect(RunService.RenderStepped, render)
			render()
			task.spawn(runSequence)
			while not closed do task.wait(0.05) end
		end)
		clean()
		if not ok then warn("[NANZ HUB V2] Intro: " .. tostring(err)) end
	end

	-- Mostrar main GUI
	main.Position = UDim2.new(originalMainPos.X.Scale, originalMainPos.X.Offset, originalMainPos.Y.Scale, originalMainPos.Y.Offset+18)
	main.Visible = true
	if miniBtn then miniBtn.Visible = false end
	TS:Create(main, TweenInfo.new(0.28, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {Position=originalMainPos}):Play()
end

