function isPackAnim(id)
	for _, pack in pairs(ANIM_PACKS) do
		for _, v in pairs(pack) do
			if v == id then return true end
		end
	end
	return false
end

function saveOriginalAnims(char)
	local animate = char:FindFirstChild("Animate")
	if not animate then return end
	local function g(obj) return obj and obj.AnimationId or nil end
	local ids = {
		idle1 = g(animate.idle and animate.idle.Animation1),
		idle2 = g(animate.idle and animate.idle.Animation2),
		walk  = g(animate.walk and animate.walk.WalkAnim),
		run   = g(animate.run  and animate.run.RunAnim),
		jump  = g(animate.jump and animate.jump.JumpAnim),
		fall  = g(animate.fall and animate.fall.FallAnim),
		climb = g(animate.climb and animate.climb.ClimbAnim),
		swim  = g(animate.swim and animate.swim.Swim),
		swimidle = g(animate.swimidle and animate.swimidle.SwimIdle),
	}
	if not isPackAnim(ids.walk) then originalTryardAnims = ids end
end

function applyAnimPack(packName)
	currentAnimPack = packName
	if animSelectorLabel then animSelectorLabel.Text = packName end
	if packName == "Off" then
		if originalTryardAnims and LP.Character then
			local animate = LP.Character:FindFirstChild("Animate")
			if animate then
				local function s(obj,id) if obj then obj.AnimationId = id end end
				s(animate.idle and animate.idle.Animation1, originalTryardAnims.idle1)
				s(animate.idle and animate.idle.Animation2, originalTryardAnims.idle2)
				s(animate.walk and animate.walk.WalkAnim, originalTryardAnims.walk)
				s(animate.run  and animate.run.RunAnim,   originalTryardAnims.run)
				s(animate.jump and animate.jump.JumpAnim, originalTryardAnims.jump)
				s(animate.fall and animate.fall.FallAnim, originalTryardAnims.fall)
				s(animate.climb and animate.climb.ClimbAnim, originalTryardAnims.climb)
				s(animate.swim and animate.swim.Swim, originalTryardAnims.swim)
				s(animate.swimidle and animate.swimidle.SwimIdle, originalTryardAnims.swimidle)
			end
		end
		if tryardHeartbeatConn then tryardHeartbeatConn:Disconnect(); tryardHeartbeatConn = nil end
		return
	end
	local pack = ANIM_PACKS[packName]
	if not pack then return end
	if tryardHeartbeatConn then tryardHeartbeatConn:Disconnect() end
	tryardHeartbeatConn = RunService.Heartbeat:Connect(function()
		local c = LP.Character
		if not c then return end
		local animate = c:FindFirstChild("Animate")
		if not animate then return end
		local function s(obj,id) if obj then obj.AnimationId = id end end
		s(animate.idle and animate.idle.Animation1, pack.idle1)
		s(animate.idle and animate.idle.Animation2, pack.idle2)
		s(animate.walk and animate.walk.WalkAnim, pack.walk)
		s(animate.run  and animate.run.RunAnim,   pack.run)
		s(animate.jump and animate.jump.JumpAnim, pack.jump)
		s(animate.fall and animate.fall.FallAnim, pack.fall)
		s(animate.climb and animate.climb.ClimbAnim, pack.climb)
		s(animate.swim and animate.swim.Swim, pack.swim)
		s(animate.swimidle and animate.swimidle.SwimIdle, pack.swimidle)
	end)
end

function startAnimPack(packName)
	local char = LP.Character
	if char then
		saveOriginalAnims(char)
		applyAnimPack(packName)
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum then
			for _, track in ipairs(hum:GetPlayingAnimationTracks()) do track:Stop(0) end
			hum:ChangeState(Enum.HumanoidStateType.Running)
		end
	else
		applyAnimPack(packName)
	end
	currentAnimPack = packName
end

function stopAnimPack()
	currentAnimPack = "Off"
	if animSelectorLabel then animSelectorLabel.Text = "Off" end
	applyAnimPack("Off")
end

if _G.__NanzAnimCharConn then pcall(function() _G.__NanzAnimCharConn:Disconnect() end) end
_G.__NanzAnimCharConn = LP.CharacterAdded:Connect(function()
	if currentAnimPack and currentAnimPack ~= "Off" then
		task.wait(0.3)
		pcall(startAnimPack, currentAnimPack)
	end
end)

-- ============================================================
--  THEME COLOR CAMPURAN (Red+Purple / Yellow+Black / Green+White, dari NANZ final)
-- ============================================================
NANZ_THEME_ORDER = {"Purple","Red + Purple","Yellow + Black","Green + White"}
NANZ_THEMES = {
	["Purple"]         = {primary=Color3.fromRGB(200,40,255), secondary=Color3.fromRGB(185,60,255), ice=Color3.fromRGB(185,60,255)},
	["Red + Purple"]   = {primary=Color3.fromRGB(255,25,40),  secondary=Color3.fromRGB(185,60,255), ice=Color3.fromRGB(185,60,255)},
	["Yellow + Black"] = {primary=Color3.fromRGB(255,232,0),  secondary=Color3.fromRGB(18,18,18),   ice=Color3.fromRGB(255,244,140)},
	["Green + White"]  = {primary=Color3.fromRGB(0,255,110),  secondary=Color3.fromRGB(252,255,253), ice=Color3.fromRGB(236,255,244)},
}
function nanzThemePalette(name)
	local t = NANZ_THEMES[name] or NANZ_THEMES["Purple"]
	local p = t.primary
	local pal = {ACCENT=p, ICE=t.ice, SEC=t.secondary}
	if name == "Purple" or not NANZ_THEMES[name] then
		pal.HOVER = Color3.fromRGB(215,100,255)
		pal.STROKE = Color3.fromRGB(123,30,160)
		pal.DARK_ACCENT = Color3.fromRGB(90,15,120)
		pal.LIGHT_GLOW = Color3.fromRGB(225,170,255)
	else
		pal.HOVER = p:Lerp(Color3.new(1,1,1), 0.3)
		pal.STROKE = p:Lerp(Color3.new(0,0,0), 0.45)
		pal.DARK_ACCENT = p:Lerp(Color3.new(0,0,0), 0.7)
		pal.LIGHT_GLOW = p:Lerp(Color3.new(1,1,1), 0.6)
	end
	return pal
end
currentThemeName = "Purple"
currentThemePal = nanzThemePalette("Purple")
ESP_COLOR = currentThemePal.ACCENT

function nanzRepaintTheme(root, oldPal, newPal)
	if not root or not oldPal or not newPal then return end
	local keys = {"ACCENT","ICE","HOVER","STROKE","DARK_ACCENT","LIGHT_GLOW"}
	local function mapc(c)
		for _, k in ipairs(keys) do
			if c == oldPal[k] then return newPal[k] end
		end
		return nil
	end
	local function mapg(c)
		if c == oldPal.SEC then return newPal.SEC end
		return mapc(c)
	end
	for _, d in ipairs(root:GetDescendants()) do
		pcall(function()
			if d:IsA("GuiObject") then
				local n = mapc(d.BackgroundColor3)
				if n then d.BackgroundColor3 = n end
				if d:IsA("TextLabel") or d:IsA("TextButton") or d:IsA("TextBox") then
					n = mapc(d.TextColor3)
					if n then d.TextColor3 = n end
				elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then
					n = mapc(d.ImageColor3)
					if n then d.ImageColor3 = n end
				end
				if d:IsA("ScrollingFrame") then
					n = mapc(d.ScrollBarImageColor3)
					if n then d.ScrollBarImageColor3 = n end
				end
			elseif d:IsA("UIStroke") then
				local n = mapc(d.Color)
				if n then d.Color = n end
			elseif d:IsA("UIGradient") then
				local out, changed = {}, false
				for i, kp in ipairs(d.Color.Keypoints) do
					local n = mapg(kp.Value)
					if n then changed = true end
					out[i] = ColorSequenceKeypoint.new(kp.Time, n or kp.Value)
				end
				if changed then d.Color = ColorSequence.new(out) end
			end
		end)
	end
end

function nanzPaintTimerLabel(lbl, pal)
	if not lbl or not lbl.Parent or not pal then return end
	pcall(function()
		local K = Color3.new(0, 0, 0)
		lbl.TextColor3 = pal.ACCENT
		local g = lbl:FindFirstChildOfClass("UIGradient")
		if g then
			g.Color = ColorSequence.new({
				ColorSequenceKeypoint.new(0, pal.ACCENT:Lerp(K, 0.25)),
				ColorSequenceKeypoint.new(0.3, pal.ACCENT),
				ColorSequenceKeypoint.new(0.5, pal.ICE),
				ColorSequenceKeypoint.new(0.7, pal.ACCENT),
				ColorSequenceKeypoint.new(1, pal.ACCENT:Lerp(K, 0.25)),
			})
		end
	end)
end

function applyNanzTheme(name)
	if not NANZ_THEMES[name] then return end
	local oldPal = currentThemePal
	local newPal = nanzThemePalette(name)
	currentThemeName = name
	currentThemePal = newPal
	ESP_COLOR = newPal.ACCENT -- ESP ikut warna tema Misc
	BLESS_COLORS.ACCENT = newPal.ACCENT
	BLESS_COLORS.ICE = newPal.ICE
	BLESS_COLORS.HOVER = newPal.HOVER
	BLESS_COLORS.STROKE = newPal.STROKE
	BLESS_COLORS.INPUT = newPal.ACCENT
	BLESS_COLORS.DARK_ACCENT = newPal.DARK_ACCENT
	BLESS_COLORS.LIGHT_GLOW = newPal.LIGHT_GLOW
	if nanzSetThemeLocals then pcall(nanzSetThemeLocals, newPal) end
	for _, nm in ipairs({UI_NAME, MOBILE_UI_NAME}) do
		local r = CoreGui:FindFirstChild(nm)
		if not r then
			local pg = LP:FindFirstChild("PlayerGui")
			r = pg and pg:FindFirstChild(nm)
		end
		if r then nanzRepaintTheme(r, oldPal, newPal) end
	end
	if nanzThemeLabel then pcall(function() nanzThemeLabel.Text = name end) end
	-- Tulisan di kepala (judul header, sub, judul HUD) ikut warna tema Misc
	pcall(function()
		local strokeC = (name == "Purple") and Color3.fromRGB(57,0,80) or newPal.ACCENT:Lerp(Color3.new(0,0,0), 0.75)
		if nanzHdrTitle then nanzHdrTitle.TextColor3 = newPal.ACCENT; nanzHdrTitle.TextStrokeColor3 = strokeC end
		if nanzHdrSub then nanzHdrSub.TextColor3 = newPal.ICE end
		if nanzHudTitle then nanzHudTitle.TextColor3 = newPal.ACCENT end
		-- Tulisan di atas kepala karakter (link discord + Speed) ikut warna tema Misc
		if speedTag and speedTag.Parent then speedTag.TextColor3 = newPal.ICE end
		local pg = LP:FindFirstChild("PlayerGui")
		local rb = pg and pg:FindFirstChild("RagCountdownBillboard")
		local rl = rb and rb:FindFirstChildWhichIsA("TextLabel", true)
		if rl then nanzPaintTimerLabel(rl, newPal) end
		if progressPctChip and progressPctChip.Parent then progressPctChip.TextColor3 = newPal.ICE end
		if speedLabel and speedLabel.Parent then speedLabel.TextColor3 = newPal.ACCENT end
		for _, lbl in pairs(otherSpeedLabels) do
			if lbl and lbl.Parent then lbl.TextColor3 = newPal.ICE end
		end
	end)
end

