		if hum.MaxHealth < maxHealth then hum.MaxHealth = maxHealth end
	end)
	_nzAntiDie.invincibleUntil = tick() + _nzAntiDie.config.invincibilityFrames
	_nzAntiDie.lastHealTime = tick()
	pcall(function()
		local char = hum.Parent
		if not char then return end
		for _, child in ipairs(char:GetChildren()) do
			if child:IsA("NumberValue") then
				local name = child.Name:lower()
				if name:find("health") or name:find("hp") or name:find("life") then
					child.Value = maxHealth
				end
			end
			if child:IsA("BoolValue") and child.Name:lower():find("dead") then
				child.Value = false
			end
		end
	end)
end

function _nzAntiDie.PreventDamage(root, hum)
	if not hum then return end
	if hum.Health < (hum.MaxHealth or 100) then _nzAntiDie.SuperHeal(hum) end
	if tick() < _nzAntiDie.invincibleUntil then
		if hum.Health < (hum.MaxHealth or 100) then
			hum.Health = hum.MaxHealth or 100
		end
	end
	if _nzAntiDie.config.ragdollProtection then
		local state = hum:GetState()
		if state == Enum.HumanoidStateType.Physics or
		   state == Enum.HumanoidStateType.Ragdoll or
		   state == Enum.HumanoidStateType.FallingDown or
		   state == Enum.HumanoidStateType.Dead then
			pcall(function()
				hum:ChangeState(Enum.HumanoidStateType.GettingUp)
				hum:ChangeState(Enum.HumanoidStateType.Running)
			end)
			_nzAntiDie.SuperHeal(hum)
			if root then
				pcall(function() root.AssemblyAngularVelocity = Vector3.zero end)
			end
		end
	end
	if hum.Health <= 0 then
		_nzAntiDie.SuperHeal(hum)
		pcall(function()
			hum:ChangeState(Enum.HumanoidStateType.GettingUp)
			hum:ChangeState(Enum.HumanoidStateType.Running)
		end)
		if root then
			pcall(function()
				root.CFrame = CFrame.new(root.Position + Vector3.new(0, 2, 0))
				root.AssemblyLinearVelocity = Vector3.zero
			end)
		end
	end
end

function _nzAntiDie.AutoRevive()
	if not _nzAntiDie.config.autoRevive then return end
	local char = LP.Character
	if not char then return end
	local hum = char:FindFirstChildOfClass("Humanoid")
	local root = char:FindFirstChild("HumanoidRootPart")
	if not hum then return end
	if hum.Health <= 0 then
		_nzAntiDie.SuperHeal(hum)
		pcall(function()
			hum:ChangeState(Enum.HumanoidStateType.GettingUp)
			hum:ChangeState(Enum.HumanoidStateType.Running)
		end)
		if root then
			pcall(function()
				root.CFrame = CFrame.new(root.Position + Vector3.new(0, 3, 0))
				root.AssemblyLinearVelocity = Vector3.zero
			end)
		end
	end
end

function _nzAntiDie.AttachHealth(char)
	if _nzAntiDie.healthConn then _nzAntiDie.healthConn:Disconnect(); _nzAntiDie.healthConn = nil end
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if not hum then hum = char and char:WaitForChild("Humanoid", 3) end
	if not hum then return end
	_nzAntiDie.healthConn = hum:GetPropertyChangedSignal("Health"):Connect(function()
		if not _nzAntiDie.enabled then return end
		if hum.Health < (hum.MaxHealth or 100) then _nzAntiDie.SuperHeal(hum) end
		if hum.Health <= 0 then _nzAntiDie.AutoRevive() end
	end)
	if hum.Health < (hum.MaxHealth or 100) then _nzAntiDie.SuperHeal(hum) end
end

function _nzAntiDie.StartEngine()
	if _nzAntiDie.enabled and _nzAntiDie.loop then return end
	_nzAntiDie.enabled = true
	_nzAntiDieEnabled = true
	nanzAntiDieFlag = true
	if _nzAntiDie.loop then _nzAntiDie.loop:Disconnect(); _nzAntiDie.loop = nil end
	if _nzAntiDie.healthConn then _nzAntiDie.healthConn:Disconnect(); _nzAntiDie.healthConn = nil end
	_nzAntiDie.loop = RunService.Heartbeat:Connect(function()
		if not _nzAntiDie.enabled then return end
		local char = LP.Character
		if not char then return end
		local hum = char:FindFirstChildOfClass("Humanoid")
		local root = char:FindFirstChild("HumanoidRootPart")
		if not hum then return end
		if hum.Health <= 0 then _nzAntiDie.AutoRevive()
		elseif hum.Health <= _nzAntiDie.config.healthThreshold then _nzAntiDie.SuperHeal(hum)
		elseif hum.Health < (hum.MaxHealth or 100) then _nzAntiDie.SuperHeal(hum) end
		_nzAntiDie.PreventDamage(root, hum)
	end)
	if LP.Character then _nzAntiDie.AttachHealth(LP.Character) end
	if _nzAntiDie.charConn then _nzAntiDie.charConn:Disconnect(); _nzAntiDie.charConn = nil end
	_nzAntiDie.charConn = LP.CharacterAdded:Connect(function(char)
		if not _nzAntiDie.enabled then return end
		task.wait(0.05)
		_nzAntiDie.AttachHealth(char)
		local hum = char:FindFirstChildOfClass("Humanoid")
		if hum then _nzAntiDie.SuperHeal(hum) end
	end)
end

function _nzAntiDie.StopEngine()
	_nzAntiDie.enabled = false
	_nzAntiDieEnabled = false
	nanzAntiDieFlag = false
	if _nzAntiDie.loop then _nzAntiDie.loop:Disconnect(); _nzAntiDie.loop = nil end
	if _nzAntiDie.healthConn then _nzAntiDie.healthConn:Disconnect(); _nzAntiDie.healthConn = nil end
	if _nzAntiDie.charConn then _nzAntiDie.charConn:Disconnect(); _nzAntiDie.charConn = nil end
	pcall(function()
		local char = LP.Character
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not hum then return end
		hum:SetStateEnabled(Enum.HumanoidStateType.Dead, true)
		hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true)
		hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
		hum.BreakJointsOnDeath = true
		if hum.MaxHealth == math.huge or hum.MaxHealth <= 0 then
			hum.MaxHealth = 100
			hum.Health = math.min(hum.Health, 100)
		end
	end)
end

function _nzAntiDieSetEnabled(enabled)
	enabled = enabled == true
	if enabled == _nzAntiDieEnabled then return end
	if enabled then
		_nzAntiDie.StartEngine()
	else
		_nzAntiDie.StopEngine()
	end
end

function _nzAntiDieRefresh()
	if _nzAntiDieStopped then return end
	local manual = _nzAntiDieSources.toggle
	_nzAntiDieSetEnabled(manual or _nzAntiDieSources.autobat)
end

_G.__NanzAntiDieSource = function(source, enabled)
	if _nzAntiDieStopped or _nzAntiDieSources[source] == nil then return end
	_nzAntiDieSources[source] = enabled == true
	_nzAntiDieRefresh()
end

_G.__NanzAntiDieSet = function(enabled)
	_G.__NanzAntiDieSource("autobat", enabled)
end

_G.__NanzAntiDieIsEnabled = function() return _nzAntiDieEnabled end
_G.__NanzAntiDieStop = function()
	_nzAntiDieStopped = true
	_nzAntiDieSources.toggle = false
	_nzAntiDieSources.autobat = false
	_nzAntiDieSetEnabled(false)
end

function nzAntiDieActivateOnCharacter(char)
	if not _nzAntiDieEnabled then return end
	_nzAntiDie.AttachHealth(char)
	local hum = char and char:FindFirstChildOfClass("Humanoid")
	if hum then _nzAntiDie.SuperHeal(hum) end
end

NanzAntiDieModule = {
	enabled = false,
	start = function()
		NanzAntiDieModule.enabled = true
		nanzAntiDieFlag = true
		_nzAntiDieStopped = false
		_G.__NanzAntiDieSource("toggle", true)
	end,
	stop = function()
		NanzAntiDieModule.enabled = false
		nanzAntiDieFlag = false
		_G.__NanzAntiDieSource("toggle", false)
	end,
}
_G.NanzAntiDie = NanzAntiDieModule

-- ============================================================
--  NORMAL V1 = AUTO STEAL dari NANZ final (engine disalin 1:1, hanya nama variabel diberi prefix nv1)
-- ============================================================
nv1Session = (_G.__NanzNV1Session or 0) + 1
_G.__NanzNV1Session = nv1Session
nv1Enabled = false
nv1Range = 61
nv1Pct, nv1Status = 0, "READY"
nv1ModeLabel, nv1RadInput, setNv1Visual = nil, nil, nil
function nv1UpdateProgress(p, status)
	nv1Pct = math.clamp(tonumber(p) or 0, 0, 1)
	nv1Status = status or nv1Status
end
function nv1RefreshRadiusLabel()
	if progressRadLbl then
		pcall(function()
			progressRadLbl.Text = string.format("Radius: %.2g", nv1Enabled and nv1Range or CONFIG.STEAL_RANGE)
		end)
	end
end
nv1Conn = nil

nv1Steal = {
	AutoStealEnabled = false,
	StealRadius = nv1Range,
	StealDuration = 1.3,
	StealDelay = 0.25,
	Data = {}
}

nv1IsStealing = false
nv1Mode = "75"
nv1Variant = 1
nv1Gen = 0
nv1StartedAt = 0
nv1LastActivity = tick()
nv1SupConn = nil
NV1_VARIANT_NAMES = {"75", "80", "85", "90", "V3", "Semi"}
function nv1SetMode(mode)
	nv1Variant = 1
	if mode == "V2" then mode = "80" elseif mode == "V1" then mode = "75" end
	for i, name in ipairs(NV1_VARIANT_NAMES) do
		if name == tostring(mode) then nv1Variant = i; break end
	end
	nv1Mode = NV1_VARIANT_NAMES[nv1Variant]
end
function nv1GetDuration()
	local factors = {0.75, 0.80, 0.85, 0.90, 1, 1}
	return nv1Steal.StealDuration * factors[nv1Variant]
end

nv1PlotsCache = nil
nv1PlotsCacheTime = 0
function nv1GetPlotsRoot()
	local now = tick()
	if nv1PlotsCache and now - nv1PlotsCacheTime < 2 and nv1PlotsCache.Parent then
		return nv1PlotsCache
	end
	nv1PlotsCache = workspace:FindFirstChild("Plots")
	nv1PlotsCacheTime = now
	return nv1PlotsCache
end

function nv1IsMyPlotByName(plotName)
	local plotsRoot = nv1GetPlotsRoot()
	if not plotsRoot then return false end
	local plot = plotsRoot:FindFirstChild(plotName)
	if not plot then return false end
	local sign = plot:FindFirstChild("PlotSign")
	if sign then
		local yb = sign:FindFirstChild("YourBase")
		if yb and yb:IsA("BillboardGui") then
			return yb.Enabled == true
		end
	end
	return false
end

function nv1FindNearestPrompt()
	local char = LP.Character
	if not char then return nil, nil end
	local root = char:FindFirstChild("HumanoidRootPart")
	if not root then return nil, nil end
	local plotsRoot = nv1GetPlotsRoot()
	if not plotsRoot then return nil, nil end
	local nearestPrompt, nearestDist, nearestName = nil, math.huge, nil
	local rpos = root.Position
	for _, plot in ipairs(plotsRoot:GetChildren()) do
		if nv1IsMyPlotByName(plot.Name) then continue end
		local pods = plot:FindFirstChild("AnimalPodiums")
		if not pods then continue end
		for _, pod in ipairs(pods:GetChildren()) do
			pcall(function()
				local base = pod:FindFirstChild("Base")
				local spawn = base and base:FindFirstChild("Spawn")
				if spawn then
					local sp = spawn.Position
					local dx = sp.X - rpos.X
					local dy = sp.Y - rpos.Y
					local dz = sp.Z - rpos.Z
					local dist = math.sqrt(dx*dx + dy*dy + dz*dz)
					if dist < nearestDist and dist <= nv1Steal.StealRadius then
						local att = spawn:FindFirstChild("PromptAttachment")
						if att then
							for _, child in ipairs(att:GetChildren()) do
								if child:IsA("ProximityPrompt") and child.ActionText and child.ActionText:find("Steal") then
									nearestPrompt = child
									nearestDist = dist
									nearestName = pod.Name
									break
								end
							end
						end
					end
				end
			end)
		end
	end
	return nearestPrompt, nearestName
end

function nv1ExecuteSteal(prompt, podName)
	if nv1IsStealing or not prompt or not prompt.Parent then return end
	for old in pairs(nv1Steal.Data) do if not old.Parent then nv1Steal.Data[old] = nil end end
	local data = nv1Steal.Data[prompt]
	if not data then
		data = {hold = {}, trigger = {}, ready = true}
		nv1Steal.Data[prompt] = data
		pcall(function()
			if type(getconnections) ~= "function" then return end
			for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
				if c.Function then table.insert(data.hold, c.Function) end
			end
			for _, c in ipairs(getconnections(prompt.Triggered)) do
				if c.Function then table.insert(data.trigger, c.Function) end
			end
		end)
	end
	if not data.ready then return end
	local generation = nv1Gen
	data.ready = false
	nv1IsStealing = true
	nv1StartedAt = tick()
	nv1LastActivity = nv1StartedAt
	local function active()
		return generation == nv1Gen and nv1IsStealing and nv1Steal.AutoStealEnabled
			and nv1Session == _G.__NanzNV1Session
	end
	local function distance()
		if not prompt.Parent or not prompt.Parent.Parent then return nil end
		local char = LP.Character
		local root = char and char:FindFirstChild("HumanoidRootPart")
		local hum = char and char:FindFirstChildOfClass("Humanoid")
		if not root or not hum or hum.Health <= 0 then return nil end
		local parent = prompt.Parent
		local part = parent:IsA("BasePart") and parent or parent.Parent
		if not part or not part:IsA("BasePart") then return nil end
		return (root.Position - part.Position).Magnitude
	end
	local function valid()
		if not active() then return false end
		local d = distance()
		return d ~= nil and d <= nv1Steal.StealRadius
	end
	task.spawn(function()
		local success, err = pcall(function()
			nv1UpdateProgress(0, "STEALING")
			for _, fn in ipairs(data.hold) do task.spawn(fn) end
			local started = tick()
			local duration = nv1Steal.StealDuration
			local stopTime = nv1GetDuration()
			while valid() and tick() - started < stopTime do
				nv1UpdateProgress((tick() - started) / duration, "STEALING")
				task.wait()
			end
			if not valid() then return end
			local stopProgress = math.clamp(stopTime / duration, 0, 1)
			nv1UpdateProgress(stopProgress, "APPROACH")
			local deadline = tick() + math.max(2.99 - stopTime - math.max(duration - stopTime, 0), 0.05)
			while valid() do
				local d = distance()
				if d and d <= 9 then break end
				if tick() >= deadline then return end
				task.wait()
			end
			if not valid() then return end
			local fillStart = tick()
			local fillDuration = math.max(duration - stopTime, 0.05)
			while valid() do
				local fp = math.clamp((tick() - fillStart) / fillDuration, 0, 1)
				nv1UpdateProgress(stopProgress + fp * (1 - stopProgress), "STEALING")
				if fp >= 1 then break end
				task.wait()
			end
			if not valid() then return end
			for _, fn in ipairs(data.trigger) do task.spawn(fn) end
			local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
			if remote and remote:IsA("RemoteEvent") and podName then pcall(function() remote:FireServer(podName) end) end
			if #data.trigger == 0 then
				if type(fireproximityprompt) == "function" then pcall(fireproximityprompt, prompt)
				else pcall(function() prompt:InputHoldBegin(); prompt:InputHoldEnd() end) end
			end
			nv1UpdateProgress(1, "COMPLETE")
			task.wait(0.12)
		end)
		data.ready = true
		if generation == nv1Gen then
			nv1IsStealing = false
			nv1StartedAt = 0
			nv1LastActivity = tick()
			nv1UpdateProgress(0, "READY")
		end
		if not success then warn("[NANZ Normal V1] " .. tostring(err)) end
	end)
end
function nv1Start()
	nv1Steal.StealRadius = nv1Variant == 6 and 10 or nv1Range
	nv1Steal.AutoStealEnabled = true
	nv1Enabled = true
	nv1LastActivity = tick()

	if nv1Conn and not nv1Conn.Connected then
		nv1Conn = nil
	end
	if nv1Conn then return true end

	nv1Conn = RunService.Heartbeat:Connect(function()
		if nv1Session ~= _G.__NanzNV1Session then
			nv1Stop()
			return
		end
		if not nv1Enabled then return end

		if not nv1Steal.AutoStealEnabled then
			nv1Steal.AutoStealEnabled = true
		end

		if nv1IsStealing then
			if nv1StartedAt > 0 and (tick() - nv1StartedAt) > 6 then
				nv1Gen = nv1Gen + 1
				nv1IsStealing = false
				nv1StartedAt = 0
				for _, data in pairs(nv1Steal.Data) do
					data.ready = true
				end
				nv1UpdateProgress(0, "READY")
			end
			return
		end

		local p, name = nv1FindNearestPrompt()
		if p then
			nv1LastActivity = tick()
			nv1ExecuteSteal(p, name)
		end
	end)
	return true
end

function nv1Stop()
	nv1Gen = nv1Gen + 1
	if nv1Conn then
		pcall(function() nv1Conn:Disconnect() end)
		nv1Conn = nil
	end
	nv1IsStealing = false
	nv1StartedAt = 0
	nv1LastActivity = tick()
	nv1Steal.AutoStealEnabled = false
	nv1Enabled = false
	for _, data in pairs(nv1Steal.Data) do data.ready = true end
	nv1UpdateProgress(0, "READY")
end

if nv1SupConn then
	pcall(function() nv1SupConn:Disconnect() end)
end
nv1SupElapsed = 0
do
	nv1SupConn = RunService.Heartbeat:Connect(function(dt)
		if nv1Session ~= _G.__NanzNV1Session then
			if nv1SupConn then
				pcall(function() nv1SupConn:Disconnect() end)
				nv1SupConn = nil
			end
			return
		end

		nv1SupElapsed = nv1SupElapsed + dt
		if nv1SupElapsed < 0.5 then return end
		nv1SupElapsed = 0

		if nv1Enabled then
			local alive = nv1Conn and nv1Conn.Connected
			if not alive or not nv1Steal.AutoStealEnabled then
				pcall(nv1Start)
			elseif nv1IsStealing and nv1StartedAt > 0 and (tick() - nv1StartedAt) > 6 then
				nv1Gen = nv1Gen + 1
				nv1IsStealing = false
				nv1StartedAt = 0
				for _, data in pairs(nv1Steal.Data) do
					data.ready = true
				end
				nv1UpdateProgress(0, "READY")
			end
		end
	end)
end


-- ============================================================
--  BODY LOCK (dipindahkan dari NANZ final -> tab COMBAT)
-- ============================================================
bodyLockEnabled = false
bodyLockRange = 20
bodyLockRangeBox = nil
bodyLockSetVisual = nil
_bodyLockConn = nil
_bodyLockHeld = false
-- Body Lock mengalah saat fitur gerak otomatis V2 sedang jalan (Auto Bat / Melee Aimbot / Auto Left / Auto Right)
function nzBodyLockBusy()
	return (autoBatEnabled or meleeAimbotEnabled or autoLeftEnabled or autoRightEnabled or (State and State.BatV2)) and true or false
end
function nzBodyLockRelease()
	_bodyLockHeld = false
	local c = LP.Character
	local hum = c and c:FindFirstChildOfClass("Humanoid")
	if hum then hum.AutoRotate = true end
end
function getClosestTargetBody()
	local char = LP.Character
	if not char then return nil end
	local root = char:FindFirstChild("HumanoidRootPart")
	if not root then return nil end
	local rpos = root.Position
	local closest, minDist = nil, math.huge
	local plist = Players:GetPlayers()
	for i = 1, #plist do
		local plr = plist[i]
		if plr ~= LP then
			local c = plr.Character
			if c then
				local tRoot = c:FindFirstChild("HumanoidRootPart")
				if tRoot then
					local hum = c:FindFirstChildOfClass("Humanoid")
					if hum and hum.Health > 0 then
						local dx = tRoot.Position.X - rpos.X
						local dy = tRoot.Position.Y - rpos.Y
						local dz = tRoot.Position.Z - rpos.Z
						local d = dx*dx + dy*dy + dz*dz
						if d < minDist then minDist = d; closest = tRoot end
					end
				end
			end
		end
	end
	return closest
end

local function _bodyLockTick()
	local char = LP.Character
	if not char then return end
	local root = char:FindFirstChild("HumanoidRootPart")
	if not root then return end
	local hum = char:FindFirstChildOfClass("Humanoid")
	if not hum then return end
	local target = getClosestTargetBody()
	if not target then
		if not hum.AutoRotate then hum.AutoRotate = true end
		return
	end
	local dist = (target.Position - root.Position).Magnitude
	if dist > bodyLockRange then
		if not hum.AutoRotate then hum.AutoRotate = true end
		return
	end
	if hum.AutoRotate then hum.AutoRotate = false end
	_bodyLockHeld = true
	local targetVel = target.AssemblyLinearVelocity
	local speed3 = targetVel.Magnitude
	local predictTime = math.clamp(speed3 / 80, 0.08, 0.35)
	local predictedPos = target.Position + targetVel * predictTime
	local targetHead = target.Parent and target.Parent:FindFirstChild("Head")
	local targetHeight = targetHead and targetHead.Position.Y or target.Position.Y
	local myHeight = root.Position.Y + (hum.HipHeight or 0)
	local heightDiff = targetHeight - myHeight
	local verticalCorrection = math.clamp(heightDiff * 0.15, -1.5, 1.5)
	local flatTarget = Vector3.new(predictedPos.X, root.Position.Y + verticalCorrection, predictedPos.Z)
	local toPredict = flatTarget - root.Position
	if toPredict.Magnitude > 0.1 then
		local goalCF = CFrame.lookAt(root.Position, flatTarget)
		local diffCF = root.CFrame:Inverse() * goalCF
		local _, ry, _ = diffCF:ToEulerAnglesXYZ()
		ry = math.clamp(ry, -2.5, 2.5)
		root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(Vector3.new(0, ry * 42, 0))
	end
end

function startBodyLock()
	if _bodyLockConn then pcall(function() _bodyLockConn:Disconnect() end); _bodyLockConn = nil end
	pcall(function() if _G.__NanzBodyLockConn then _G.__NanzBodyLockConn:Disconnect() end end)
	-- nomor sesi: loop lama (termasuk dari eksekusi sebelumnya) otomatis mati kalau nomornya beda
	_G.__NanzBodyLockSession = (_G.__NanzBodyLockSession or 0) + 1
	local mySession = _G.__NanzBodyLockSession
	local acc = 0
	local conn
	conn = RunService.Heartbeat:Connect(function(dt)
		if _G.__NanzBodyLockSession ~= mySession then
			if conn then conn:Disconnect() end
			return
		end
		if not bodyLockEnabled then return end
		if nzBodyLockBusy() then
			if _bodyLockHeld then nzBodyLockRelease() end
			return
		end
		acc = acc + dt
		if acc < 0.033 then return end
		acc = 0
		_bodyLockTick()
	end)
	_bodyLockConn = conn
	_G.__NanzBodyLockConn = conn
end

function stopBodyLock()
	_bodyLockHeld = false
	_G.__NanzBodyLockSession = (_G.__NanzBodyLockSession or 0) + 1 -- matikan semua loop Body Lock (juga yang yatim)
	if _bodyLockConn then
		pcall(function() _bodyLockConn:Disconnect() end)
		_bodyLockConn = nil
	end
	pcall(function() if _G.__NanzBodyLockConn then _G.__NanzBodyLockConn:Disconnect() end end)
	_G.__NanzBodyLockConn = nil
	local c = LP.Character
	local root = c and c:FindFirstChild("HumanoidRootPart")
	if root then
		root.AssemblyAngularVelocity = Vector3.zero
		root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, -0.1, root.AssemblyLinearVelocity.Z)
	end
	local hum2 = c and c:FindFirstChildOfClass("Humanoid")
	if hum2 then hum2.AutoRotate = true end
	-- pastikan benar-benar lepas: ~0.7 dtk setelah OFF, tahan AutoRotate=true selama tidak ada fitur lock lain yang aktif
	task.spawn(function()
		for _ = 1, 40 do
			RunService.Heartbeat:Wait()
			if bodyLockEnabled then return end -- dinyalakan lagi -> berhenti
			if nzBodyLockBusy() or (State and State.BatV2) then return end
			local ch = LP.Character
			local h = ch and ch:FindFirstChildOfClass("Humanoid")
			local r = ch and ch:FindFirstChild("HumanoidRootPart")
			if h and not h.AutoRotate then h.AutoRotate = true end
			if r and r.AssemblyAngularVelocity.Magnitude > 0.5 then r.AssemblyAngularVelocity = Vector3.zero end
		end
	end)
