	local function clampMini()
		if not (miniBtn and miniBtn.Parent) then return end
		local vs=gui.AbsoluteSize
		local bw,bh=miniBtn.AbsoluteSize.X,miniBtn.AbsoluteSize.Y
		if vs.X<=0 or vs.Y<=0 or bw<=0 then return end
		local ap=miniBtn.AbsolutePosition
		local x=math.clamp(ap.X-gui.AbsolutePosition.X,0,math.max(vs.X-bw,0))
		local y=math.clamp(ap.Y-gui.AbsolutePosition.Y,0,math.max(vs.Y-bh,0))
