				mDown=true;mMoved=false;mInput=i;mStart=i.Position;mOrigin=miniBtn.AbsolutePosition-gui.AbsolutePosition
				i.Changed:Connect(function()
					if i.UserInputState==Enum.UserInputState.End then
						mDown=false
						clampMini()
						if mMoved then task.delay(0.12,function() miniDragged=false end) end
					end
				end)
			end
		end)
		UIS.InputChanged:Connect(function(i)
			if not mDown or not mStart then return end
			if i==mInput or (i.UserInputType==Enum.UserInputType.MouseMovement and mInput and mInput.UserInputType==Enum.UserInputType.MouseButton1) then
				local dx,dy=i.Position.X-mStart.X,i.Position.Y-mStart.Y
				if not mMoved and (math.abs(dx)>6 or math.abs(dy)>6) then mMoved=true;miniDragged=true end
				if mMoved then
					local vs=gui.AbsoluteSize
					local x=math.clamp(mOrigin.X+dx,0,math.max(vs.X-miniBtn.AbsoluteSize.X,0))
					local y=math.clamp(mOrigin.Y+dy,0,math.max(vs.Y-miniBtn.AbsoluteSize.Y,0))
					miniBtn.Position=UDim2.new(0,x,0,y)
				end
			end
		end)
		gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(clampMini)
		miniBtn:GetPropertyChangedSignal("AbsoluteSize"):Connect(clampMini)
		clampMini()
		-- penjaga: jika menu tertutup dan tombol OPEN tidak terlihat (di luar intro), munculkan lagi
