	-- ============================================================
	--  STEAL POD: ukuran (besar/kecil), lock/unlock geser, dibatasi tepi layar HP
	-- ============================================================
	do
		local podUiScale=Instance.new("UIScale",pbFrame);podUiScale.Scale=stealPodScale or 1
		local function clampPod()
			local sz=gui.AbsoluteSize
			if sz.X<=0 or sz.Y<=0 then return end
			local ap,as=pbFrame.AbsolutePosition,pbFrame.AbsoluteSize
			local cx=math.clamp(ap.X,0,math.max(0,sz.X-as.X))
			local cy=math.clamp(ap.Y,0,math.max(0,sz.Y-as.Y))
			if cx~=ap.X or cy~=ap.Y then
				local p=pbFrame.Position
				pbFrame.Position=UDim2.new(p.X.Scale,p.X.Offset+(cx-ap.X),p.Y.Scale,p.Y.Offset+(cy-ap.Y))
			end
		end
		local function clampLater() task.defer(function() task.wait(0.05);pcall(clampPod) end) end
		stealPodSavePos=function()
			local sz=gui.AbsoluteSize;local ap=pbFrame.AbsolutePosition
			if sz.X>0 and sz.Y>0 then stealPodPos={fx=ap.X/sz.X,fy=ap.Y/sz.Y} end
		end
		stealPodApplyScale=function(s)
			s=math.clamp(tonumber(s) or 1,0.5,2)
			stealPodScale=s;podUiScale.Scale=s
			clampLater()
		end
		stealPodApplyLock=function(lock)
			stealPodLocked=lock and true or false
			pbFrame.Active=not stealPodLocked
		end
		stealPodApplyPos=function(p)
			if type(p)~="table" or type(p.fx)~="number" or type(p.fy)~="number" then return end
			pbFrame.Position=UDim2.new(math.clamp(p.fx,0,1),0,math.clamp(p.fy,0,1),0)
			clampLater()
		end
		local dragging,dInput,dStart,dPos,dAbs=false,nil,nil,nil,nil
		pbFrame.InputBegan:Connect(function(input)
			if stealPodLocked then return end
			if input.UserInputType~=Enum.UserInputType.Touch and input.UserInputType~=Enum.UserInputType.MouseButton1 then return end
			dragging=true;dInput=input;dStart=input.Position;dPos=pbFrame.Position;dAbs=pbFrame.AbsolutePosition
			input.Changed:Connect(function()
				if input.UserInputState==Enum.UserInputState.End or input.UserInputState==Enum.UserInputState.Cancel then
					dragging=false;dInput=nil
					pcall(clampPod);pcall(stealPodSavePos)
					saveConfig()
				end
			end)
		end)
		UIS.InputChanged:Connect(function(input)
			if not dragging or stealPodLocked or not dStart or not dPos or not dAbs then return end
			if dInput and dInput.UserInputType==Enum.UserInputType.Touch and input~=dInput then return end
			if input.UserInputType~=Enum.UserInputType.Touch and input.UserInputType~=Enum.UserInputType.MouseMovement then return end
			local sz=gui.AbsoluteSize;local as=pbFrame.AbsoluteSize
			local tx=math.clamp(dAbs.X+(input.Position.X-dStart.X),0,math.max(0,sz.X-as.X))
			local ty=math.clamp(dAbs.Y+(input.Position.Y-dStart.Y),0,math.max(0,sz.Y-as.Y))
			pbFrame.Position=UDim2.new(dPos.X.Scale,dPos.X.Offset+(tx-dAbs.X),dPos.Y.Scale,dPos.Y.Offset+(ty-dAbs.Y))
		end)
		gui:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() pcall(clampPod) end)
		stealPodApplyLock(stealPodLocked)
		clampLater()
	end

