	-- Lebar GUI 240: label menyesuaikan lebar kontrol di kanannya; kalau terlalu sempit,
	-- label dipindah ke baris atas dan kontrol turun ke bawah supaya teks tidak saling tindih
	local ROW_W=GUI_W-(PAD*3+TAB_W)-4
	local function fitLabel(row,l)
		if not row.Parent or not l.Parent then return end
		local minX=ROW_W
		local ctrls={}
		for _,c in ipairs(row:GetChildren()) do
			if c~=l and c:IsA("GuiObject") and c.Size.X.Scale<0.9 then
				local px=c.Position.X.Scale*ROW_W+c.Position.X.Offset
				if px<minX then minX=px end
				ctrls[#ctrls+1]=c
			end
		end
		local avail=minX-14
		if avail>=56 then
			l.Size=UDim2.new(0,avail,1,0)
		else
			l.Size=UDim2.new(1,-20,0,13);l.Position=UDim2.new(0,10,0,3);l.TextWrapped=false
			local add=14
			row.Size=UDim2.new(row.Size.X.Scale,row.Size.X.Offset,0,row.Size.Y.Offset+add)
			for _,c in ipairs(ctrls) do
				local p,sz=c.Position,c.Size
				if sz.Y.Scale>=0.9 then
					c.Position=UDim2.new(p.X.Scale,p.X.Offset,p.Y.Scale,p.Y.Offset+add)
					c.Size=UDim2.new(sz.X.Scale,sz.X.Offset,sz.Y.Scale,sz.Y.Offset-add)
				else
					c.Position=UDim2.new(p.X.Scale,p.X.Offset,p.Y.Scale,p.Y.Offset+add/2+1)
				end
			end
		end
	end
	local function mkLabel(row,txt)
		local l=Instance.new("TextLabel",row);l.Size=UDim2.new(0.5,0,1,0);l.Position=UDim2.new(0,10,0,0);l.BackgroundTransparency=1;l.Text=txt;l.TextColor3=W;l.Font=Enum.Font.GothamBold;l.TextSize=8;l.TextXAlignment=Enum.TextXAlignment.Left
		l.TextWrapped=true;l.TextTruncate=Enum.TextTruncate.AtEnd
		task.defer(function() pcall(fitLabel,row,l) end)
		return l
	end
	local function mkPill(row,offset)
		local pill=Instance.new("Frame",row);pill.Size=UDim2.new(0,36,0,18);pill.Position=UDim2.new(1,-(offset or 44),0.5,-9);pill.BackgroundColor3=OFF;pill.BorderSizePixel=0;pill.ZIndex=3
		Instance.new("UICorner",pill).CornerRadius=UDim.new(1,0)
		local dot=Instance.new("Frame",pill);dot.Size=UDim2.new(0,12,0,12);dot.Position=UDim2.new(0,3,0.5,-6);dot.BackgroundColor3=DIM;dot.BorderSizePixel=0;dot.ZIndex=4
		Instance.new("UICorner",dot).CornerRadius=UDim.new(1,0)
		return pill,dot
	end
	local function animPill(pill,dot,on)
		TS:Create(pill,TweenInfo.new(0.18,Enum.EasingStyle.Quad),{BackgroundColor3=on and ICE or OFF}):Play()
		TS:Create(dot,TweenInfo.new(0.18,Enum.EasingStyle.Back),{Position=on and UDim2.new(1,-15,0.5,-6) or UDim2.new(0,3,0.5,-6),BackgroundColor3=on and Color3.fromRGB(0,0,0) or DIM}):Play()
	end
	local function mkToggle(parent,txt,cb)
		local row=mkRow(parent,ROW_H,true);mkLabel(row,txt);local pill,dot=mkPill(row,46);local on=false
		local function sv(s) on=s;animPill(pill,dot,s) end
