-- ============================================================
--  NANZ ANTI BAT⚡
--  Anti Drop | Anti Die | Anti Bat | Hold Jump | Win Detect
--  Tombol "nanz anti bat⚡" / "ANTI BAT" (sama seperti tombol lain) = ON/OFF semua fitur
-- ============================================================
do
local okAll,errAll=pcall(function()
	local Players=game:GetService("Players")
	local RunService=game:GetService("RunService")
	local UIS=game:GetService("UserInputService")
	local TweenService=game:GetService("TweenService")
	local HttpService=game:GetService("HttpService")
	local CoreGui=game:GetService("CoreGui")
	local Workspace=game:GetService("Workspace")
	local LP=Players.LocalPlayer

	local BRAND="nanz anti bat⚡"

	local C_BORDER=Color3.fromRGB(180,180,180)
	local C_PANEL=Color3.fromRGB(15,15,15)
	local C_TEXT_TITLE=Color3.fromRGB(255,255,255)
	local C_TEXT_SUB=Color3.fromRGB(200,200,200)
	local C_INACTIVE=Color3.fromRGB(255,80,100)
	local C_ACTIVE=Color3.fromRGB(100,255,120)
	local C_TOGGLE_ON=Color3.fromRGB(200,200,200)
	local C_TOGGLE_OFF=Color3.fromRGB(40,40,40)

	local GUI_WIDTH=200
	local GUI_EXPANDED_HEIGHT=236
	local GUI_COLLAPSED_HEIGHT=35

	-- ---------- config ----------
	local ConfigFile="NANZ_AntiBat_Config.json"
	local Config={
		Position={X_Scale=0.5,X_Offset=-100,Y_Scale=0.5,Y_Offset=-100},
		TogglePos={X_Scale=0,X_Offset=10,Y_Scale=0.62,Y_Offset=0},
		AntiDrop=false,AntiDie=false,AntiBat=false,HoldJump=false,
		IsCollapsed=false,GuiVisible=false,AntiDieKey="H"
	}
	local function SaveConfig()
		if writefile then pcall(function() writefile(ConfigFile,HttpService:JSONEncode(Config)) end) end
	end
	do
		if isfile and readfile and isfile(ConfigFile) then
			local ok,data=pcall(function() return HttpService:JSONDecode(readfile(ConfigFile)) end)
			if ok and type(data)=="table" then for k,v in pairs(data) do Config[k]=v end end
		end
	end

	local Keys={antiDie=Enum.KeyCode.H,guiHide=Enum.KeyCode.RightControl}
	pcall(function() if Config.AntiDieKey and Enum.KeyCode[Config.AntiDieKey] then Keys.antiDie=Enum.KeyCode[Config.AntiDieKey] end end)

	-- ---------- helpers ----------
	local function corner(o,r) local c=Instance.new("UICorner",o);c.CornerRadius=UDim.new(0,r);return c end
	local function newScreenGui(name,order)
		local g=Instance.new("ScreenGui")
		g.Name=name;g.ResetOnSpawn=false;g.DisplayOrder=order or 10;g.IgnoreGuiInset=true;g.ZIndexBehavior=Enum.ZIndexBehavior.Sibling
		if not pcall(function() g.Parent=CoreGui end) or not g.Parent then g.Parent=LP:WaitForChild("PlayerGui") end
		return g
	end
	for _,name in ipairs({"NanzAntiBatUI","NanzAntiBatBillboard","NanzAntiBatToggle","NanzAntiBatToast"}) do
		pcall(function() local o=CoreGui:FindFirstChild(name);if o then o:Destroy() end end)
		pcall(function() local pg=LP:FindFirstChild("PlayerGui");local o=pg and pg:FindFirstChild(name);if o then o:Destroy() end end)
	end

	-- ============================================================
	--  BILLBOARD (tulisan di atas kepala saat Anti Drop aktif)
	-- ============================================================
	local billboardGui,billboardFrame,billboardUpdater,billboardCharAddedConn=nil,nil,nil,nil
	local function createBillboard(char)
		if not char then return end
		local head=char:FindFirstChild("Head");if not head then return end
		if billboardGui then billboardGui:Destroy();billboardGui=nil end
		if billboardUpdater then billboardUpdater:Disconnect();billboardUpdater=nil end
		billboardGui=newScreenGui("NanzAntiBatBillboard",10)
		billboardFrame=Instance.new("Frame",billboardGui)
		billboardFrame.Size=UDim2.new(0,170,0,30);billboardFrame.BackgroundColor3=Color3.fromRGB(0,0,0);billboardFrame.BackgroundTransparency=0.3;billboardFrame.BorderSizePixel=0
		corner(billboardFrame,8)
		local txt=Instance.new("TextLabel",billboardFrame)
		txt.Size=UDim2.new(1,0,1,0);txt.BackgroundTransparency=1;txt.Text=BRAND;txt.TextColor3=Color3.fromRGB(255,255,255);txt.Font=Enum.Font.GothamBlack;txt.TextSize=16
		billboardUpdater=RunService.Heartbeat:Connect(function()
			if not billboardGui or not billboardGui.Parent then
				if billboardUpdater then billboardUpdater:Disconnect();billboardUpdater=nil end
				return
			end
			if not head or not head.Parent then billboardFrame.Visible=false;return end
			local cam=Workspace.CurrentCamera;if not cam then return end
			local pos,onScreen=cam:WorldToScreenPoint(head.Position)
			if onScreen then
				billboardFrame.Position=UDim2.new(0,pos.X-85,0,pos.Y-40);billboardFrame.Visible=true
			else billboardFrame.Visible=false end
		end)
	end
	local function destroyBillboard()
		if billboardUpdater then billboardUpdater:Disconnect();billboardUpdater=nil end
		if billboardGui then billboardGui:Destroy();billboardGui=nil end
		billboardFrame=nil
		if billboardCharAddedConn then billboardCharAddedConn:Disconnect();billboardCharAddedConn=nil end
	end

	-- ============================================================
	--  LOGIKA: ANTI DROP (spoof velocity)
	-- ============================================================
	local mt=getrawmetatable and getrawmetatable(game) or nil
	local oldIdx,oldNewIdx
	local spoofedVelocity=Vector3.zero
	local antiDropActive=false
	local function startAntiDrop()
		if antiDropActive then return end
		if not (mt and setreadonly and newcclosure and checkcaller) then warn("[NANZ ANTI BAT] executor tidak support Anti Drop");return end
		oldIdx=mt.__index;oldNewIdx=mt.__newindex
		setreadonly(mt,false)
		mt.__index=newcclosure(function(self,key)
			if not checkcaller() and (key=="AssemblyLinearVelocity" or key=="Velocity") and typeof(self)=="Instance" and self:IsA("BasePart") and self.Name=="HumanoidRootPart" and LP.Character and self:IsDescendantOf(LP.Character) then
				return spoofedVelocity
			end
			return oldIdx(self,key)
		end)
		mt.__newindex=newcclosure(function(self,key,value)
			if not checkcaller() and (key=="AssemblyLinearVelocity" or key=="Velocity") and typeof(self)=="Instance" and self:IsA("BasePart") and self.Name=="HumanoidRootPart" and LP.Character and self:IsDescendantOf(LP.Character) then
				spoofedVelocity=value
				return
			end
			return oldNewIdx(self,key,value)
		end)
		setreadonly(mt,true)
		antiDropActive=true
		if LP.Character then createBillboard(LP.Character) end
		if billboardCharAddedConn then billboardCharAddedConn:Disconnect() end
		billboardCharAddedConn=LP.CharacterAdded:Connect(function(c)
			if Config.AntiDrop then task.wait(0.1);createBillboard(c) end
		end)
	end
	local function stopAntiDrop()
		if not antiDropActive then return end
		if mt and oldIdx then
			setreadonly(mt,false)
			mt.__index=oldIdx;mt.__newindex=oldNewIdx
			setreadonly(mt,true)
			oldIdx=nil;oldNewIdx=nil
		end
		antiDropActive=false
		destroyBillboard()
	end

	-- ============================================================
	--  LOGIKA: ANTI DIE
	-- ============================================================
	local heartConn,deathConns,charAddedConn=nil,{},nil
	local function clearDeathConns()
		for _,c in ipairs(deathConns) do pcall(function() c:Disconnect() end) end
		deathConns={}
	end
	local function protectChar(character)
		if not character then return end
		local hum=character:WaitForChild("Humanoid",5);if not hum then return end
		hum.MaxHealth=math.huge;hum.Health=math.huge
		table.insert(deathConns,hum.StateChanged:Connect(function(_,new)
			if not Config.AntiDie then return end
			if new==Enum.HumanoidStateType.Dead then
				hum.Health=math.huge;hum:SetStateEnabled(Enum.HumanoidStateType.Dead,false)
			end
		end))
		hum:SetStateEnabled(Enum.HumanoidStateType.Dead,false)
		table.insert(deathConns,hum:GetPropertyChangedSignal("Health"):Connect(function()
			if not Config.AntiDie then return end
			if hum.Health<hum.MaxHealth then hum.Health=math.huge end
		end))
		if heartConn then heartConn:Disconnect() end
		heartConn=RunService.Heartbeat:Connect(function()
			if not Config.AntiDie then return end
			if hum and hum.Parent and hum.Health<hum.MaxHealth then hum.Health=math.huge end
		end)
	end
	local function startAntiDie()
		clearDeathConns()
		if heartConn then heartConn:Disconnect();heartConn=nil end
		if charAddedConn then charAddedConn:Disconnect();charAddedConn=nil end
		task.spawn(protectChar,LP.Character)
		charAddedConn=LP.CharacterAdded:Connect(function(c)
			if not Config.AntiDie then return end
			task.wait(0.1)
			clearDeathConns()
			protectChar(c)
		end)
	end
	local function stopAntiDie()
		clearDeathConns()
		if heartConn then heartConn:Disconnect();heartConn=nil end
		if charAddedConn then charAddedConn:Disconnect();charAddedConn=nil end
		local char=LP.Character
		local hum=char and char:FindFirstChildOfClass("Humanoid")
		if hum then
			hum:SetStateEnabled(Enum.HumanoidStateType.Dead,true)
			hum.MaxHealth=100;hum.Health=100
		end
	end

