			root.Velocity=Vector3.new(AntiBatForceX,root.Velocity.Y,AntiBatForceZ)
			RunService.RenderStepped:Wait()
			if root and root.Parent then root.Velocity=Vector3.new(origXZ.X,root.Velocity.Y,origXZ.Z) end
		end)
	end
