	-- ============================================================
	--  WIN DETECT (duel) - notifikasi lokal saja
	-- ============================================================
	task.spawn(function()
		local COOLDOWN=5
		local lastWin=0
		local toastGui=newScreenGui("NanzAntiBatToast",13)
		local toast=Instance.new("TextLabel",toastGui)
		toast.Size=UDim2.new(0,260,0,28);toast.AnchorPoint=Vector2.new(0.5,0);toast.Position=UDim2.new(0.5,0,0,12)
		toast.BackgroundColor3=Color3.fromRGB(0,0,0);toast.BackgroundTransparency=0.25;toast.TextColor3=Color3.fromRGB(255,255,255)
		toast.Font=Enum.Font.GothamBlack;toast.TextSize=12;toast.Visible=false;toast.Text=""
		corner(toast,8)
		local toastId=0
		local function showToast(text)
			toastId=toastId+1;local id=toastId
			toast.Text=text;toast.Visible=true
			task.delay(4,function() if toastId==id then toast.Visible=false end end)
		end

		local function stripTags(text) return text and (text:gsub("<[^>]+>","")) or "" end
		local function formatShortNumber(n)
			if n>=1e12 then return string.format("%.1fT",n/1e12) end
			if n>=1e9 then return string.format("%.1fB",n/1e9) end
			if n>=1e6 then return string.format("%.1fM",n/1e6) end
			if n>=1e3 then return string.format("%.1fK",n/1e3) end
			return tostring(math.floor(n))
		end
		local function parseNumber(value)
			local str=tostring(value):gsub("%s","")
			local num,suffix=str:match("([%d%.]+)(%a?)")
			num=tonumber(num) or 0
			suffix=(suffix or ""):upper()
			if suffix=="K" then num=num*1e3 elseif suffix=="M" then num=num*1e6 elseif suffix=="B" then num=num*1e9 elseif suffix=="T" then num=num*1e12 end
			return num
		end
		local function getBrainrot()
			local p3=Vector3.new(-476.752,10.464,7.107)
			local p7=Vector3.new(-476.752,10.464,114.107)
			local mine
			for _,v in ipairs(Workspace:GetDescendants()) do
				if v:IsA("BasePart") and v.Name=="PlotSign" then
					local d3=(v.Position-p3).Magnitude
					local d7=(v.Position-p7).Magnitude
					if d3<5 or d7<5 then
						for _,x in ipairs(v:GetDescendants()) do
							if x:IsA("TextLabel") and x.Text~="" then
								if x.Text:find(LP.Name,1,true) or x.Text:find(LP.DisplayName,1,true) then mine=(d3<5) and 3 or 7 end
							end
						end
					end
				end
			end
			if not mine then return "Unknown","N/A" end
			local targetPos=(mine==3) and p7 or p3
			local debris=Workspace:FindFirstChild("Debris")
			if not debris then return "Unknown","N/A" end
			local bestName,bestVal
			for _,v in ipairs(debris:GetChildren()) do
				if v.Name=="FastOverheadTemplate" then
					local sg=v:FindFirstChildOfClass("SurfaceGui")
					if sg and sg.Adornee and (sg.Adornee.Position-targetPos).Magnitude<=50 then
						local gen=sg:FindFirstChild("Generation",true)
						if gen and gen:IsA("TextLabel") then
							local val=parseNumber(gen.Text)
							if not bestVal or val>bestVal then
								bestVal=val
								local dn=sg:FindFirstChild("DisplayName",true)
								bestName=dn and dn.Text or v.Name
							end
						end
					end
				end
			end
			return bestName or "Unknown",bestVal and formatShortNumber(bestVal) or "N/A"
		end
		local function onWin()
			if tick()-lastWin<COOLDOWN then return end
			lastWin=tick()
			local br,val=getBrainrot()
			print(string.format("[NANZ ANTI BAT] WIN | %s | %s",tostring(br),tostring(val)))
			showToast("WIN | "..tostring(br).." | "..tostring(val))
		end
		local function scanUIElement(obj)
			if not (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then return end
			local clean=stripTags(obj.Text):lower()
			if clean:find(LP.Name:lower(),1,true) and clean:find("won the duel",1,true) then onWin() end
		end
		local playerGui=LP:WaitForChild("PlayerGui")
		local function hookUIElement(v)
			scanUIElement(v)
			if v:IsA("TextLabel") or v:IsA("TextButton") or v:IsA("TextBox") then
				v:GetPropertyChangedSignal("Text"):Connect(function() scanUIElement(v) end)
			end
		end
		for _,v in ipairs(playerGui:GetDescendants()) do hookUIElement(v) end
		playerGui.DescendantAdded:Connect(hookUIElement)
	end)
end)
if not okAll then warn("[NANZ ANTI BAT] gagal load: "..tostring(errAll)) end
end

-- ============================================================
-- COOLDOWN TIMER (dipindahkan persis dari Clean: hitung mundur 2.5 detik di atas kepala
-- saat karakter ragdoll / jatuh, lalu tampil "READY!")
-- ============================================================
xpcall(function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local LP = Players.LocalPlayer
local _V3new = Vector3.new

do
    local _ragCountdownRunning = false
    local function _getRagBillboard()
        local char = LP.Character
        if not char then return nil, nil end
        local head = char:FindFirstChild("Head")
        if not head then return nil, nil end
        local pGui = LP.PlayerGui
        local existing = pGui:FindFirstChild("RagCountdownBillboard")
        if existing then existing:Destroy() end
        local bb = Instance.new("BillboardGui")
        bb.Name = "RagCountdownBillboard"
        bb.Size = UDim2.new(0, 84, 0, 42)
        bb.StudsOffset = _V3new(0, 7.0, 0)
        bb.AlwaysOnTop = true
        bb.Adornee = head
        bb.Parent = pGui
        local lbl = Instance.new("TextLabel")
        lbl.Size = UDim2.new(1, 0, 1, 0)
        lbl.AnchorPoint = Vector2.new(0.5, 0.5)
        lbl.Position = UDim2.new(0.5, 0, 0.5, 0)
        lbl.BackgroundTransparency = 1
        lbl.Font = Enum.Font.GothamBlack
        lbl.TextScaled = true
        lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
        lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        lbl.TextStrokeTransparency = 1
        lbl.Text = ""
        lbl.Parent = bb
        local grad = Instance.new("UIGradient", lbl)
        grad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(200, 200, 210)),
            ColorSequenceKeypoint.new(0.3, Color3.new(1, 1, 1)),
            ColorSequenceKeypoint.new(0.5, Color3.new(1, 1, 1)),
            ColorSequenceKeypoint.new(0.7, Color3.new(1, 1, 1)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(200, 200, 210)),
        })
        grad.Rotation = 45
        grad.Offset = Vector2.new(0, 0)
        if nanzPaintTimerLabel and currentThemePal then nanzPaintTimerLabel(lbl, currentThemePal) end
        return bb, lbl
    end

    local function _ragPunch(lbl, text)
        if not (lbl and lbl.Parent) then return end
        lbl.Text = text
    end

    local function _startRagCountdown()
        if _ragCountdownRunning then return end
        _ragCountdownRunning = true
        task.spawn(function()
            local bb, lbl = _getRagBillboard()
            if not bb then _ragCountdownRunning = false; return end
            local timeLeft = 2.5
            local step = 0.1
            while timeLeft > 0 and bb.Parent do
                _ragPunch(lbl, string.format("%.1f", timeLeft))
                task.wait(step)
                timeLeft = timeLeft - step
            end
            if bb and bb.Parent then
                _ragPunch(lbl, "READY!")
                task.wait(0.5)
                if bb and bb.Parent then bb:Destroy() end
            end
            _ragCountdownRunning = false
        end)
    end

    if _G.__NanzV2TimerConn then pcall(function() _G.__NanzV2TimerConn:Disconnect() end) end
    local _wasRagdolled = false
    local _ragConn
    _ragConn = RunService.Heartbeat:Connect(function()
        local char = LP.Character
        if not char then _wasRagdolled = false; return end
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not hum or hum.Health <= 0 then _wasRagdolled = false; return end
        local st = hum:GetState()
        local inRag = st == Enum.HumanoidStateType.Physics
                   or st == Enum.HumanoidStateType.Ragdoll
                   or st == Enum.HumanoidStateType.FallingDown
        if inRag and not _wasRagdolled then
            _wasRagdolled = true
            _startRagCountdown()
        elseif not inRag then
            _wasRagdolled = false
        end
    end)
    _G.__NanzV2TimerConn = _ragConn
end
end, function(e) warn("[NANZ HUB V2] Cooldown Timer gagal dimuat: " .. tostring(e)) end)
